using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Data;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
using Newtonsoft.Json.Linq;

namespace Bolsover.Gears.Gui
{
    /// <summary>
    /// A simple WinForms user control that accepts JSON in the format generated by GearVariableExporter
    /// and displays the contained variables (design and calculated) in a tabular grid.
    /// </summary>
    public class GearVariableJsonViewerControl : UserControl
    {
        private readonly DataGridView _grid;
        private readonly Label _headerLabel;

        /// <summary>
        /// Initializes a new instance of <see cref="GearVariableJsonViewerControl"/>.
        /// </summary>
        public GearVariableJsonViewerControl()
        {
            Dock = DockStyle.Fill;
            var layout = new TableLayoutPanel
            {
                Dock = DockStyle.Fill,
                ColumnCount = 1,
                RowCount = 2,
                Padding = new Padding(6),
            };
            layout.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            layout.RowStyles.Add(new RowStyle(SizeType.Percent, 100));

            _headerLabel = new Label
            {
                Text = "Gear Variables",
                AutoSize = true,
                Font = new Font(FontFamily.GenericSansSerif, 10f, FontStyle.Bold),
                Dock = DockStyle.Top,
                Margin = new Padding(0, 0, 0, 6)
            };

            _grid = new DataGridView
            {
                Dock = DockStyle.Fill,
                AutoGenerateColumns = false,
                AllowUserToAddRows = false,
                AllowUserToDeleteRows = false,
                ReadOnly = true,
                RowHeadersVisible = false,
                SelectionMode = DataGridViewSelectionMode.FullRowSelect,
            };

            // Define columns: Category (Design/Calculated), Name, Symbol, Formula, Value
            _grid.Columns.Add(new DataGridViewTextBoxColumn
            {
                HeaderText = "Category",
                DataPropertyName = nameof(RowModel.Category),
                AutoSizeMode = DataGridViewAutoSizeColumnMode.AllCells
            });
            _grid.Columns.Add(new DataGridViewTextBoxColumn
            {
                HeaderText = "Ordinal",
                DataPropertyName = nameof(RowModel.Ordinal),
                AutoSizeMode = DataGridViewAutoSizeColumnMode.AllCells
            });
            _grid.Columns.Add(new DataGridViewTextBoxColumn
            {
                HeaderText = "Name",
                DataPropertyName = nameof(RowModel.Name),
                AutoSizeMode = DataGridViewAutoSizeColumnMode.Fill
            });
            _grid.Columns.Add(new DataGridViewTextBoxColumn
            {
                HeaderText = "Symbol",
                DataPropertyName = nameof(RowModel.Symbol),
                AutoSizeMode = DataGridViewAutoSizeColumnMode.Fill
            });
            _grid.Columns.Add(new DataGridViewTextBoxColumn
            {
                HeaderText = "Formula",
                DataPropertyName = nameof(RowModel.Formula),
                AutoSizeMode = DataGridViewAutoSizeColumnMode.Fill
            });
            _grid.Columns.Add(new DataGridViewTextBoxColumn
            {
                HeaderText = "NCalc",
                DataPropertyName = nameof(RowModel.NCalc),
                AutoSizeMode = DataGridViewAutoSizeColumnMode.Fill
            });
            _grid.Columns.Add(new DataGridViewTextBoxColumn
            {
                HeaderText = "Value",
                DataPropertyName = nameof(RowModel.Value),
                AutoSizeMode = DataGridViewAutoSizeColumnMode.AllCells,
                DefaultCellStyle = new DataGridViewCellStyle { Format = "F4" }
            });

            layout.Controls.Add(_headerLabel, 0, 0);
            layout.Controls.Add(_grid, 0, 1);
            Controls.Add(layout);
        }

        /// <summary>
        /// Sets the caption at the top of the grid (optional, can display context/mode).
        /// </summary>
        public string Caption
        {
            get => _headerLabel.Text;
            set => _headerLabel.Text = value;
        }

        /// <summary>
        /// Loads JSON text produced by GearVariableExporter and displays it in the grid.
        /// </summary>
        /// <param name="json">JSON string with structure matching GearVariableExporter output.</param>
        public void LoadJson(string json)
        {
            if (string.IsNullOrWhiteSpace(json))
            {
                BindRows(new List<RowModel>());
                return;
            }

            try
            {
                var obj = JObject.Parse(json);
                LoadJObject(obj);
            }
            catch (Exception)
            {
                // On invalid JSON, just clear the grid; consumers can handle errors externally if desired.
                BindRows(new List<RowModel>());
            }
        }

        /// <summary>
        /// Loads a pre-parsed JObject containing GearVariableExporter output.
        /// </summary>
        public void LoadJObject(JObject obj)
        {
            if (obj == null)
            {
                BindRows(new List<RowModel>());
                return;
            }

            var context = obj["context"]?.ToString();
            var mode = obj["mode"]?.ToString();
            if (!string.IsNullOrEmpty(context) || !string.IsNullOrEmpty(mode))
            {
                Caption = $"Gear Variables{(string.IsNullOrEmpty(context) ? string.Empty : $" — {context}")}{(string.IsNullOrEmpty(mode) ? string.Empty : $" ({mode})")}";
            }

            var rows = new List<RowModel>();
            var variables = obj["variables"] as JObject;
            if (variables != null)
            {
                AppendArray(rows, variables["calculated"] as JArray, "Calculated");
                AppendArray(rows, variables["design"] as JArray, "Design");
            }

            // Stable sort by Category then Name
            rows = rows
                .OrderBy(r => r.Ordinal)
                .ThenBy(r => r.Category)
                .ThenBy(r => r.Name)
                .ToList();

            BindRows(rows);
        }

        private static void AppendArray(List<RowModel> rows, JArray? array, string category)
        {
            if (array == null) return;
            foreach (var token in array)
            {
                if (token is not JObject item) continue;
                rows.Add(new RowModel
                {
                    Category = category,
                    Name = item["name"]?.ToString(),
                    Ordinal = item["ordinal"]?.ToObject<int?>(),
                    Symbol = item["symbol"]?.ToString(),
                    Formula = item["formula"]?.ToString(),
                    NCalc = item["ncalc"]?.ToString(),
                    Value = item["value"]?.ToObject<double?>()
                });
            }
        }

        private void BindRows(IList<RowModel> rows)
        {
            // Using BindingList for smoother WinForms data binding
            _grid.DataSource = new BindingList<RowModel>(rows.ToList());
        }

        private class RowModel
        {
            public string Category { get; set; }
            public string Name { get; set; }
            public int? Ordinal { get; set; }
            public string Symbol { get; set; }
            public string Formula { get; set; }
            public string NCalc { get; set; }
            public double? Value { get; set; }
        }
    }
}
